  define('LastIndex','마지막 배열 인덱스','int',[],'return int(array.size())-1;',a=>a.array.length-1);
  define('IsEmpty','빈 배열','bool',[],'return array.empty();',a=>a.array.length===0);
  define('IsValidIndex','유효한 배열 인덱스','bool',[['int','index']],'return index>=0&&index<int(array.size());',a=>a.index>=0&&a.index<a.array.length,{index:1});
  define('Get','배열 원소 읽기',type,[['int','index']],'if(index<0||index>=int(array.size()))throw std::out_of_range("array index");return array[index];',a=>{if(a.index<0||a.index>=a.array.length)throw Error('배열 인덱스 오류');return structuredClone(a.array[a.index]);},{index:1});
  define('Find','배열 원소 찾기','int',[[type,'item']],'for(int i=0;i<int(array.size());i++)if(hb_detail::equal('+type+'(array[i]),item))return i;return -1;',a=>a.array.findIndex(v=>equal(v,a.item)),{item});
  define('Contains','배열 원소 포함','bool',[[type,'item']],'for(auto v:array)if(hb_detail::equal('+type+'(v),item))return true;return false;',a=>a.array.some(v=>equal(v,a.item)),{item});
