  define('Append','배열 합친 사본',array,[[array,'other']],'auto r=array;r.insert(r.end(),other.begin(),other.end());if(r.size()>128)throw std::length_error("array limit");return r;',a=>{const v=[...a.array,...a.other];if(v.length>128)throw Error('배열 크기 제한');return v;},{other:[item]});
